<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MobileX</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="/public/assets/css/site.css"></head><body class="bg-slate-950 text-slate-100"><header class="sticky top-0 z-10 border-b border-slate-800 bg-slate-950/90"><nav class="mx-auto flex max-w-7xl items-center justify-between p-4"><a class="text-2xl font-black" href="?page=home">Mobile<span class="text-blue-400">X</span></a><div class="flex gap-4"><a href="?page=products">Sản phẩm</a><a href="?page=checkout">Giỏ hàng</a><?php if(!empty($_SESSION['user']['id'])): ?><a href="?page=profile">Tài khoản</a><a href="?page=orders">Đơn hàng</a><?php else: ?><a href="?page=login">Đăng nhập</a><?php endif ?><a href="?page=track-orders">Tra cứu đơn</a></div></nav></header>
<main class="mx-auto max-w-7xl p-5"><section id="banner-slides" class="relative"><?php $bannerIndex=0; foreach($homeBanners as $b): ?><a href="<?= $e($b['target_url']?:'?page=products') ?>" class="banner-slide relative min-h-64 overflow-hidden rounded-2xl bg-slate-900 <?= $bannerIndex++===0?'':'hidden' ?>"><img src="<?= $e($b['image_path']) ?>" alt="<?= $e($b['title']) ?>" class="absolute inset-0 h-full w-full object-cover opacity-50"><div class="relative p-8"><h1 class="text-3xl font-bold"><?= $e($b['title']) ?></h1><span class="mt-6 inline-block rounded bg-blue-600 px-4 py-2">Khám phá</span></div></a><?php endforeach ?><?php if(!$homeBanners): ?><div class="rounded-2xl bg-gradient-to-r from-blue-900 to-slate-900 p-10"><p class="text-blue-300">MOBILEX STORE</p><h1 class="my-3 text-4xl font-bold">Thiết bị công nghệ chính hãng</h1><a href="?page=products" class="inline-block rounded bg-blue-600 px-5 py-3">Mua sắm ngay</a></div><?php endif ?></section>
<?php if($liveFlashProducts): ?><section class="my-10"><div class="flex items-center justify-between"><h2 class="text-2xl font-bold">Flash Sale</h2><span class="rounded bg-red-800 px-3 py-1">Ưu đãi đang diễn ra</span></div><div class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><?php foreach($liveFlashProducts as $p): ?><article class="rounded-xl bg-slate-900 p-5"><p class="text-sm text-red-300"><?= $e($p['campaign_name']) ?></p><h3 class="my-2 font-bold"><?= $e($p['name']) ?></h3><p><del class="text-slate-500"><?= number_format((float)$p['original_price'],0,',','.') ?> ₫</del></p><p class="text-2xl font-bold text-red-300"><?= number_format((float)$p['sale_price'],0,',','.') ?> ₫</p><p class="text-sm">Còn <?= (int)$p['stock_quantity'] ?></p><p class="countdown text-xs text-amber-300" data-seconds="<?= (int)$p['remaining_seconds'] ?>"></p><a href="?page=detail&amp;product_id=<?= (int)$p['id'] ?>" class="mt-3 inline-block rounded bg-red-700 px-3 py-2">Chọn phiên bản</a></article><?php endforeach ?></div></section><?php endif ?>
<section class="my-10"><div class="flex justify-between"><h2 class="text-2xl font-bold">Sản phẩm nổi bật</h2><a class="text-blue-300" href="?page=products">Xem tất cả →</a></div><div class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><?php foreach(array_slice($featuredProducts,0,8) as $p): ?><a href="?page=detail&amp;product_id=<?= (int)$p['id'] ?>" class="rounded-xl bg-slate-900 p-5"><div class="flex h-36 items-center justify-center text-5xl">📱</div><h3 class="font-bold"><?= $e($p['name']) ?></h3><p class="mt-2 text-blue-300"><?= number_format((float)$p['price'],0,',','.') ?> ₫</p></a><?php endforeach ?></div><?php if(!$featuredProducts): ?><p class="mt-4 text-slate-400">Sản phẩm sẽ hiển thị khi được kích hoạt.</p><?php endif ?></section><section class="my-10"><h2 class="text-2xl font-bold">Top sellers</h2><div class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><?php foreach($topProducts as $p): ?><a class="rounded-xl bg-slate-900 p-5" href="?page=detail&amp;product_id=<?= (int)$p['id'] ?>"><h3 class="font-bold"><?= $e($p['name']) ?></h3><p class="mt-2 text-blue-300"><?= number_format((float)$p['price'],0,',','.') ?> VND ? <?= (int)$p['sold'] ?> sold</p></a><?php endforeach ?><?php if(!$topProducts): ?><p class="text-slate-400">No completed sales yet.</p><?php endif ?></div></section><section class="my-10"><h2 class="text-2xl font-bold">Accessories</h2><div class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><?php foreach($accessoryProducts as $p): ?><a class="rounded-xl bg-slate-900 p-5" href="?page=detail&amp;product_id=<?= (int)$p['id'] ?>"><h3 class="font-bold"><?= $e($p['name']) ?></h3><p class="mt-2 text-blue-300"><?= number_format((float)$p['price'],0,',','.') ?> ?</p></a><?php endforeach ?><?php if(!$accessoryProducts): ?><p class="text-slate-400">No accessories available yet.</p><?php endif ?></div></section></main>
<script>const slides=[...document.querySelectorAll('.banner-slide')];if(slides.length>1){let index=0;setInterval(()=>{slides[index].classList.add('hidden');index=(index+1)%slides.length;slides[index].classList.remove('hidden')},5000)}document.querySelectorAll('.countdown').forEach(el=>{let n=Number(el.dataset.seconds);const tick=()=>{if(n<=0){el.textContent='Đã kết thúc';return}const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;el.textContent=`Kết thúc sau ${h}g ${m}p ${s}s`;n--};tick();setInterval(tick,1000)});</script></body></html>
